create or replace function public.create_qr_engagement_program(p_qr_code_id uuid,p_program_type text,p_name text,p_description text default null,p_reward_config jsonb default '{}'::jsonb,p_trigger_count integer default 1) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid; begin insert into public.qr_engagement_programs(qr_code_id,program_type,name,description,reward_config,trigger_count) values(p_qr_code_id,p_program_type,p_name,p_description,coalesce(p_reward_config,'{}'::jsonb),greatest(coalesce(p_trigger_count,1),1)) returning id into v_id; return v_id; end; $$;
create or replace function public.list_qr_engagement_programs(p_qr_code_id uuid) returns setof public.qr_engagement_programs language sql security definer set search_path=public as $$ select * from public.qr_engagement_programs where qr_code_id=p_qr_code_id and active order by created_at desc; $$;
create or replace function public.get_cross_tier_leaderboard(p_leaderboard_key text default 'consumer_checkins',p_limit integer default 25) returns table(actor_id uuid,actor_type text,total_value numeric,rank bigint) language sql security definer set search_path=public as $$ select actor_id,actor_type,sum(metric_value),rank() over(order by sum(metric_value) desc) from public.network_leaderboard_participation where leaderboard_key=p_leaderboard_key group by actor_id,actor_type order by sum(metric_value) desc limit greatest(p_limit,1); $$;
